//Methods implementation

void CatiaLuaAddin::CreateCommands()
{
	// Start the in-process Lua RPC server (localhost only, port 19529).
	CatiaLuaRpcStart(19529);

	new CatiaLuaCmdHeader("RunLua","CatiaLuaCmd","CmdLuaRunner",(void*)NULL);
}

CATCmdContainer * CatiaLuaAddin::CreateToolbars()
{


	//创建命令条
	NewAccess(CATCmdContainer,pLuaTlb,CatiaLua);

	NewAccess(CATCmdStarter,pRunLua, RunLua);
	SetAccessCommand(pRunLua, "RunLua");
	SetAccessChild(pLuaTlb, pRunLua);










	
	AddToolbarView(pLuaTlb, 1, Right);

	/**********************************************************************/

	//创建菜单
	NewAccess(CATCmdContainer, pLuaMbr, EchoMbr);
	NewAccess(CATCmdContainer, pLuaM, CatiaLua);
	SetAccessChild(pLuaMbr, pLuaM);
	NewAccess(CATCmdStarter,pRunLuaM, RunLuaM);
	SetAccessCommand(pRunLuaM, "RunLua");
	SetAccessChild(pLuaM, pRunLuaM);








	//////////////////////////////////////////////////////////////////////////

	SetAddinMenu(pLuaTlb, pLuaMbr);

	return pLuaTlb;
	//return NULL;
}